cd /workspace && cat > src/main.rs << 'EOF'
use clap::{Parser, Subcommand};
use std::path::PathBuf;

mod parser;
mod database;
mod cards;
mod export;
mod check;
mod stats;
mod web;
mod orphans;

use parser::parse_deck;
use database::CardDatabase;
use std::path::Path;

#[derive(Parser)]
#[command(name = "hashcards")]
#[command(about = "A plain text-based spaced repetition system")]
#[command(version = "0.3.0")]
struct Args {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Drill cards through a web interface
    Drill {
        /// Path to the collection directory. By default, the current working directory is used
        #[arg(default_value = ".")]
        directory: PathBuf,

        /// Maximum number of cards to drill in a session
        #[arg(long)]
        card_limit: Option<usize>,

        /// Maximum number of new cards to drill in a session
        #[arg(long)]
        new_card_limit: Option<usize>,

        /// The host address to bind to
        #[arg(long, default_value = "127.0.0.1")]
        host: String,

        /// The port to use for the web server
        #[arg(long, default_value = "8000")]
        port: u16,

        /// Only drill cards from this deck
        #[arg(long)]
        from_deck: Option<String>,

        /// Whether to open the browser automatically
        #[arg(long, default_value = "true")]
        open_browser: String,

        /// Which answer controls to show
        #[arg(long, default_value = "full")]
        answer_controls: String,

        /// Whether or not to bury siblings
        #[arg(long, default_value = "true")]
        bury_siblings: String,
    },

    /// Check the integrity of a collection
    Check {
        /// Path to the collection directory
        #[arg(default_value = ".")]
        directory: PathBuf,
    },

    /// Print collection statistics
    Stats {
        /// Path to the collection directory
        #[arg(default_value = ".")]
        directory: PathBuf,

        /// Which output format to use
        #[arg(long, default_value = "html")]
        format: String,
    },

    /// Commands relating to orphan cards
    Orphans {
        #[command(subcommand)]
        subcommand: OrphansCommand,
    },

    /// Export a collection
    Export {
        /// Path to the collection directory
        #[arg(default_value = ".")]
        directory: PathBuf,

        /// Optional path to the output file
        #[arg(long)]
        output: Option<PathBuf>,
    },
}

#[derive(Subcommand)]
enum OrphansCommand {
    /// List the hashes of all orphan cards
    List {
        #[arg(default_value = ".")]
        directory: PathBuf,
    },
    /// Remove all orphan cards from the database
    Delete {
        #[arg(default_value = ".")]
        directory: PathBuf,
    },
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    match args.command {
        Commands::Drill {
            directory,
            card_limit,
            new_card_limit,
            host,
            port,
            from_deck,
            open_browser,
            answer_controls,
            bury_siblings,
        } => {
            web::run_web_interface(
                &directory,
                card_limit,
                new_card_limit,
                &host,
                port,
                from_deck.as_deref(),
                &open_browser,
                &answer_controls,
                &bury_siblings,
            )
            .await?;
        }

        Commands::Check { directory } => {
            check::check_collection(&directory)?;
        }

        Commands::Stats { directory, format } => {
            stats::print_stats(&directory, &format)?;
        }

        Commands::Orphans { subcommand } => {
            match subcommand {
                OrphansCommand::List { directory } => {
                    orphans::list_orphans(&directory)?;
                }
                OrphansCommand::Delete { directory } => {
                    orphans::delete_orphans(&directory)?;
                }
            }
        }

        Commands::Export {
            directory,
            output,
        } => {
            export::export_collection(&directory, output.as_deref())?;
        }
    }

    Ok(())
}
EOF

