use serde::{Deserialize, Serialize};
use std::path::PathBuf;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Card {
    pub hash: String,
    pub family_hash: Option<String>,
    pub deck_name: String,
    pub location: CardLocation,
    pub content: CardContent,
    pub performance: Option<CardPerformance>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CardLocation {
    #[serde(rename = "filePath")]
    pub file_path: String,
    #[serde(rename = "lineStart")]
    pub line_start: usize,
    #[serde(rename = "lineEnd")]
    pub line_end: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum CardContent {
    #[serde(rename = "basic")]
    Basic { basic: BasicCard },
    #[serde(rename = "cloze")]
    Cloze { cloze: ClozeCard },
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BasicCard {
    pub question: String,
    pub answer: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ClozeCard {
    pub text: String,
    pub start: usize,
    pub end: usize,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct CardPerformance {
    pub interval: i32,
    pub ease: f32,
    pub repetitions: i32,
    pub next_review: i64,
}

impl CardContent {
    pub fn basic(question: String, answer: String) -> Self {
        CardContent::Basic {
            basic: BasicCard { question, answer },
        }
    }

    pub fn cloze(text: String, start: usize, end: usize) -> Self {
        CardContent::Cloze {
            cloze: ClozeCard { text, start, end },
        }
    }
}
EOF

