use crate::cards::{Card, CardContent, CardLocation};
use regex::Regex;
use sha2::{Digest, Sha256};
use std::path::Path;

pub struct ParsedDeck {
    pub deck_name: String,
    pub cards: Vec<Card>,
    pub tex_macros: Vec<String>,
}

pub fn parse_deck(file_path: &Path, deck_name: &str) -> anyhow::Result<ParsedDeck> {
    let content = std::fs::read_to_string(file_path)?;
    let cards = parse_cards(&content, file_path.to_string_lossy().to_string(), deck_name)?;

    // Extract TeX macros
    let tex_macros = extract_tex_macros(&content);

    Ok(ParsedDeck {
        deck_name: deck_name.to_string(),
        cards,
        tex_macros,
    })
}

fn parse_cards(
    content: &str,
    file_path: String,
    deck_name: &str,
) -> anyhow::Result<Vec<Card>> {
    let mut cards = Vec::new();

    // Split by double newlines to find card blocks
    let blocks: Vec<&str> = content.split("\n\n").collect();
