use rusqlite::{Connection, params, OptionalExtension};
use std::path::Path;
use anyhow::Result;

pub struct CardDatabase {
    conn: Connection,
}

impl CardDatabase {
    pub fn new(collection_path: &Path) -> Result<Self> {
        let db_path = collection_path.join("hashcards.db");
        let conn = Connection::open(&db_path)?;

        // Initialize tables
        conn.execute_batch(
            "CREATE TABLE IF NOT EXISTS cards (
                hash TEXT PRIMARY KEY,
                family_hash TEXT,
                deck_name TEXT NOT NULL,
                file_path TEXT NOT NULL,
                line_start INTEGER NOT NULL,
                line_end INTEGER NOT NULL,
                interval INTEGER NOT NULL DEFAULT 1,
                ease REAL NOT NULL DEFAULT 2.5,
                repetitions INTEGER NOT NULL DEFAULT 0,
                next_review INTEGER NOT NULL DEFAULT 0
            );
            CREATE TABLE IF NOT EXISTS sessions (
                id TEXT PRIMARY KEY,
                created_at INTEGER NOT NULL,
                cards_reviewed INTEGER NOT NULL DEFAULT 0
            );
        ")?;

        Ok(CardDatabase { conn })
    }

    pub fn card_exists(&self, hash: &str) -> Result<bool> {
        let exists: bool = self
            .conn
            .query_row(
                "SELECT EXISTS(SELECT 1 FROM cards WHERE hash = ?1)",
                [hash],
                |row| row.get(0),
            )?;
        Ok(exists)
    }

    pub fn get_card_count(&self) -> Result<usize> {
        let count: usize = self
            .conn
            .query_row("SELECT COUNT(*) FROM cards", [], |row| row.get(0))?;
        Ok(count)
    }

    pub fn insert_or_update_card(
        &self,
        hash: &str,
        family_hash: Option<&str>,
        deck_name: &str,
        file_path: &str,
        line_start: usize,
        line_end: usize,
    ) -> Result<()> {
        self.conn.execute(
            "INSERT OR IGNORE INTO cards (hash, family_hash, deck_name, file_path, line_start, line_end)
             VALUES (?1, ?2, ?3, ?4, ?5, ?6)",
            params![hash, family_hash, deck_name, file_path, line_start, line_end],
        )?;
        Ok(())
    }

    pub fn get_all_hashes(&self) -> Result<Vec<String>> {
        let mut stmt = self.conn.prepare("SELECT hash FROM cards")?;
        let hashes = stmt
