cd /workspace && cat > src/export.rs << 'EOF'
use crate::parser::parse_deck;
use crate::cards::Card;
use serde_json::{json, Value};
use std::path::{Path, PathBuf};
use walkdir::WalkDir;
use std::fs;

pub fn export_collection(collection_path: &Path, output_path: Option<&Path>) -> anyhow::Result<()> {
    let mut all_cards = Vec::new();
    let mut sessions = Vec::new();

    // Parse all .md files in the collection
    for entry in WalkDir::new(collection_path)
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| e.path().extension().map_or(false, |ext| ext == "md"))
    {
        let file_path = entry.path();

        // Skip files in hidden directories
        if file_path.components().any(|c| {
            c.as_os_str().to_string_lossy().starts_with('.')
        }) {
            continue;
        }

        let deck_name = file_path
            .file_stem()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_default();

        if let Ok(parsed) = parse_deck(file_path, &deck_name) {
            all_cards.extend(parsed.cards);
        }
    }

    let export_data = json!({
        "cards": all_cards,
        "sessions": sessions
    });

    let json_str = serde_json::to_string_pretty(&export_data)?;

    if let Some(output) = output_path {
        fs::write(output, json_str)?;
    } else {
        println!("{}", json_str);
    }

    Ok(())
}
EOF

