use crate::parser::parse_deck;
use crate::database::CardDatabase;
use serde_json::json;
use std::path::Path;
use walkdir::WalkDir;

pub fn print_stats(collection_path: &Path, format: &str) -> anyhow::Result<()> {
    if format == "html" {
        println!("HTML output is not implemented yet.");
        return Ok(());
    }

    // Parse all cards
    let mut total_cards = 0;
    let mut tex_macro_count = 0;

    for entry in WalkDir::new(collection_path)
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| e.path().extension().map_or(false, |ext| ext == "md"))
    {
        let file_path = entry.path();

        // Skip hidden files
        if file_path.components().any(|c| {
            c.as_os_str().to_string_lossy().starts_with('.')
        }) {
            continue;
        }

        let deck_name = file_path
            .file_stem()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_default();

        if let Ok(parsed) = parse_deck(file_path, &deck_name) {
            total_cards += parsed.cards.len();
            tex_macro_count += parsed.tex_macros.len();
        }
    }

    // Get database stats
    let db = CardDatabase::new(collection_path)?;
    let cards_in_db = db.get_card_count()?;

    let stats = json!({
        "cardsInDeckCount": total_cards,
        "cardsInDbCount": cards_in_db,
        "texMacroCount": tex_macro_count,
        "cardsReviewedTodayCount": 0
    });

    println!("{}", serde_json::to_string_pretty(&stats)?);
    Ok(())
}
EOF

