use crate::parser::parse_deck;
use crate::database::CardDatabase;
use std::path::Path;
use std::collections::HashSet;
use walkdir::WalkDir;

pub fn list_orphans(collection_path: &Path) -> anyhow::Result<()> {
    // Get all hashes from deck files
    let mut deck_hashes = HashSet::new();

    for entry in WalkDir::new(collection_path)
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| e.path().extension().map_or(false, |ext| ext == "md"))
    {
        let file_path = entry.path();

        // Skip hidden files
        if file_path.components().any(|c| {
            c.as_os_str().to_string_lossy().starts_with('.')
        }) {
            continue;
        }

        let deck_name = file_path
            .file_stem()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_default();

        if let Ok(parsed) = parse_deck(file_path, &deck_name) {
            for card in parsed.cards {
                deck_hashes.insert(card.hash);
            }
        }
    }

    // Get all hashes from database
    let db = CardDatabase::new(collection_path)?;
    let db_hashes = db.get_all_hashes()?;

    // Find orphans (in DB but not in decks)
    for hash in db_hashes {
        if !deck_hashes.contains(&hash) {
            println!("{}", hash);
        }
    }

    Ok(())
}

pub fn delete_orphans(collection_path: &Path) -> anyhow::Result<()> {
    // Get all hashes from deck files
    let mut deck_hashes = HashSet::new();

    for entry in WalkDir::new(collection_path)
        .into_iter()
        .filter_map(|e| e.ok())
        .filter(|e| e.path().extension().map_or(false, |ext| ext == "md"))
    {
        let file_path = entry.path();

        // Skip hidden files
        if file_path.components().any(|c| {
            c.as_os_str().to_string_lossy().starts_with('.')
        }) {
            continue;
        }

        let deck_name = file_path
            .file_stem()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_default();

        if let Ok(parsed) = parse_deck(file_path, &deck_name) {
            for card in parsed.cards {
                deck_hashes.insert(card.hash);
            }
        }
    }

    // Get all hashes from database
    let db = CardDatabase::new(collection_path)?;
    let db_hashes = db.get_all_hashes()?;

    // Delete orphans
    for hash in db_hashes {
        if !deck_hashes.contains(&hash) {
            db.delete_card(&hash)?;
        }
    }

    Ok(())
}
