use std::fmt;

#[derive(Debug, Clone)]
pub struct Card {
    pub hash: String,
    pub family_hash: Option<String>,
    pub deck_name: String,
    pub file_path: String,
    pub line_start: usize,
    pub line_end: usize,
    pub content: CardContent,
    pub performance: Option<CardPerformance>,
}

#[derive(Debug, Clone)]
pub enum CardContent {
    Basic { question: String, answer: String },
    Cloze { text: String, start: usize, end: usize },
}

#[derive(Debug, Clone)]
pub struct CardPerformance {
    pub interval: i32,
    pub ease: f32,
    pub repetitions: i32,
    pub next_review: i64,
}

impl fmt::Display for CardContent {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            CardContent::Basic { question, answer } => {
                write!(f, "Q: {}\nA: {}", question, answer)
            }
            CardContent::Cloze { text, start, end } => {
                write!(f, "C: {} {} {}", text, start, end)
            }
        }
    }
}
