use crate::cards::{Card, CardContent};
use std::path::Path;

pub struct ParsedDeck {
    pub deck_name: String,
    pub cards: Vec<Card>,
    pub tex_macros: Vec<String>,
}

pub fn parse_deck(file_path: &Path, deck_name: &str) -> std::io::Result<ParsedDeck> {
    let content = std::fs::read_to_string(file_path)?;
    let cards = parse_cards(&content, file_path.to_string_lossy().to_string(), deck_name)?;

    // Extract TeX macros
    let tex_macros = extract_tex_macros(&content);

    Ok(ParsedDeck {
        deck_name: deck_name.to_string(),
        cards,
        tex_macros,
    })
}

fn parse_cards(
    content: &str,
    file_path: String,
    deck_name: &str,
) -> std::io::Result<Vec<Card>> {
    let mut cards = Vec::new();

    // Split by double newlines to find card blocks
    let blocks: Vec<&str> = content.split("\n\n").collect();
    let mut line_offset = 0;

    for block in blocks {
        let trimmed = block.trim();
        if trimmed.is_empty() {
            line_offset += block.matches('\n').count() + 1;
            continue;
        }

        let line_start = line_offset;
        let line_count = block.matches('\n').count();
        let line_end = line_offset + line_count;

        if trimmed.starts_with("Q:") {
            // Basic card (Question/Answer)
            if let Some(card) = parse_basic_card(trimmed, &file_path, deck_name, line_start, line_end)
            {
                cards.push(card);
            }
        } else if trimmed.starts_with("C:") {
            // Cloze card
            let cloze_cards = parse_cloze_card(trimmed, &file_path, deck_name, line_start, line_end);
            cards.extend(cloze_cards);
        }

        line_offset = line_end + 1;
    }

    Ok(cards)
}

fn parse_basic_card(
    block: &str,
    file_path: &str,
    deck_name: &str,
    line_start: usize,
    line_end: usize,
) -> Option<Card> {
    let lines: Vec<&str> = block.lines().collect();

    let mut question_lines = Vec::new();
    let mut answer_start = 0;
    let mut found_answer = false;

    for (i, line) in lines.iter().enumerate() {
        if found_answer {
            answer_start = i;
            break;
        }
        if line.starts_with("A:") {
            found_answer = true;
            answer_start = i;
            break;
        }
        if line.starts_with("Q:") {
            question_lines.push(line[2..].trim().to_string());
        } else if i > 0 {
            question_lines.push(line.to_string());
        }
    }

    if !found_answer || answer_start >= lines.len() {
        return None;
    }

    let question = question_lines.join("\n").trim().to_string();
    let mut answer_lines = Vec::new();
    let mut in_answer = false;

    for (i, line) in lines.iter().enumerate() {
        if i == answer_start {
            let answer_part = line[2..].trim();
            if !answer_part.is_empty() {
                answer_lines.push(answer_part.to_string());
            }
            in_answer = true;
        } else if in_answer {
            answer_lines.push(line.to_string());
        }
    }

    let answer = answer_lines.join("\n").trim().to_string();

    let content_str = format!("Q: {}\nA: {}", question, answer);
    let hash = compute_hash(&content_str);

    Some(Card {
        hash,
        family_hash: None,
        deck_name: deck_name.to_string(),
        file_path: file_path.to_string(),
        line_start,
        line_end,
        content: CardContent::Basic { question, answer },
        performance: None,
    })
}

fn parse_cloze_card(
    block: &str,
    file_path: &str,
    deck_name: &str,
    line_start: usize,
    line_end: usize,
) -> Vec<Card> {
    let mut cards = Vec::new();

    // Remove "C:" prefix
    let content = if let Some(stripped) = block.strip_prefix("C:") {
        stripped.trim().to_string()
    } else {
        return cards;
    };

    // Find all cloze deletions [text]
    let mut cloze_positions = Vec::new();
    let mut in_bracket = false;
    let mut bracket_start = 0;

    for (i, ch) in content.chars().enumerate() {
        if ch == '[' {
            in_bracket = true;
            bracket_start = i;
        } else if ch == ']' && in_bracket {
            in_bracket = false;
            cloze_positions.push((bracket_start, i));
        }
    }

    for (cloze_start, cloze_end) in cloze_positions {
        let hash = compute_hash(&format!("{}\x00{}\x00{}", content, cloze_start, cloze_end));
        let family_hash = compute_hash(&content);

        cards.push(Card {
            hash,
            family_hash: Some(family_hash),
            deck_name: deck_name.to_string(),
            file_path: file_path.to_string(),
            line_start,
            line_end,
            content: CardContent::Cloze {
                text: content.clone(),
                start: cloze_start,
                end: cloze_end,
            },
            performance: None,
        });
    }

    cards
}

fn compute_hash(content: &str) -> String {
    let output = std::process::Command::new("sha256sum")
        .arg("-")
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .spawn()
        .and_then(|mut child| {
            use std::io::Write;
            if let Some(mut stdin) = child.stdin.take() {
                stdin.write_all(content.as_bytes())?;
            }
            child.wait_with_output()
        });

    match output {
        Ok(output) => {
            let output_str = String::from_utf8_lossy(&output.stdout);
            output_str.split_whitespace().next().unwrap_or("").to_string()
        }
        Err(_) => "error".to_string(),
    }
}

fn extract_tex_macros(content: &str) -> Vec<String> {
    let mut macros = Vec::new();

    for line in content.lines() {
        if line.contains("\\newcommand") {
            macros.push(line.to_string());
        }
    }

    macros
}
