use std::env;
use std::path::Path;
use std::process;

mod parser;
mod cards;
mod export;
mod check;
mod stats;
mod orphans;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        process::exit(0);
    }

    let command = &args[1];

    match command.as_str() {
        "drill" => {
            handle_drill(&args);
        }
        "check" => {
            handle_check(&args);
        }
        "stats" => {
            handle_stats(&args);
        }
        "orphans" => {
            handle_orphans(&args);
        }
        "export" => {
            handle_export(&args);
        }
        "help" | "-h" | "--help" => {
            print_help();
        }
        "--version" | "-V" => {
            println!("hashcards 0.3.0");
        }
        _ => {
            eprintln!("Unknown command: {}", command);
            print_help();
            process::exit(1);
        }
    }
}

fn print_help() {
    println!("A plain text-based spaced repetition system.

Usage: executable <COMMAND>

Commands:
  drill    Drill cards through a web interface
  check    Check the integrity of a collection
  stats    Print collection statistics
  orphans  Commands relating to orphan cards
  export   Export a collection
  help     Print this message or the help of the given subcommand(s)

Options:
  -h, --help     Print help
  -V, --version  Print version");
}

fn handle_drill(_args: &[String]) {
    eprintln!("Web interface not yet implemented");
}

fn handle_check(args: &[String]) {
    let directory = if args.len() > 2 {
        &args[2]
    } else {
        "."
    };

    if let Err(e) = check::check_collection(Path::new(directory)) {
        eprintln!("Error: {}", e);
        process::exit(1);
    }
}

fn handle_stats(args: &[String]) {
    let mut directory = ".".to_string();
    let mut format = "html".to_string();

    let mut i = 2;
    while i < args.len() {
        match args[i].as_str() {
            "--format" => {
                if i + 1 < args.len() {
                    format = args[i + 1].clone();
                    i += 2;
                } else {
                    i += 1;
                }
            }
            arg if !arg.starts_with("--") => {
                directory = arg.to_string();
                i += 1;
            }
            _ => i += 1,
        }
    }

    if let Err(e) = stats::print_stats(Path::new(&directory), &format) {
        eprintln!("Error: {}", e);
        process::exit(1);
    }
}

fn handle_orphans(args: &[String]) {
    if args.len() < 3 {
        println!("Commands relating to orphan cards

Usage: executable orphans <COMMAND>

Commands:
  list    List the hashes of all orphan cards in the collection
  delete  Remove all orphan cards from the database
  help    Print this message or the help of the given subcommand(s)

Options:
  -h, --help  Print help");
        return;
    }

    let subcommand = &args[2];
    let directory = if args.len() > 3 { &args[3] } else { "." };

    match subcommand.as_str() {
        "list" => {
            if let Err(e) = orphans::list_orphans(Path::new(directory)) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        }
        "delete" => {
            if let Err(e) = orphans::delete_orphans(Path::new(directory)) {
                eprintln!("Error: {}", e);
                process::exit(1);
            }
        }
        _ => {
            eprintln!("Unknown orphans subcommand: {}", subcommand);
            process::exit(1);
        }
    }
}

fn handle_export(args: &[String]) {
    let mut directory = ".".to_string();
    let mut output: Option<String> = None;

    let mut i = 2;
    while i < args.len() {
        match args[i].as_str() {
            "--output" => {
                if i + 1 < args.len() {
                    output = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    i += 1;
                }
            }
            arg if !arg.starts_with("--") => {
                directory = arg.to_string();
                i += 1;
            }
            _ => i += 1,
        }
    }

    if let Err(e) = export::export_collection(
        Path::new(&directory),
        output.as_deref().map(Path::new),
    ) {
        eprintln!("Error: {}", e);
        process::exit(1);
    }
}
