cd /workspace && cat > src/export.rs << 'EOF'
use crate::parser::parse_deck;
use std::path::{Path};
use std::fs;

pub fn export_collection(collection_path: &Path, output_path: Option<&Path>) -> std::io::Result<()> {
    let mut all_cards = Vec::new();

    // Parse all .md files in the collection
    for entry in fs::read_dir(collection_path)? {
        let entry = entry?;
        let path = entry.path();

        if path.is_file() && path.extension().map_or(false, |ext| ext == "md") {
            let file_name = path.file_stem().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();

            if let Ok(parsed) = parse_deck(&path, &file_name) {
                for card in parsed.cards {
                    all_cards.push(card);
                }
            }
        }
    }

    // Convert to JSON manually
    let mut json = String::from("{\n  \"cards\": [\n");

    for (i, card) in all_cards.iter().enumerate() {
        if i > 0 {
            json.push_str(",\n");
        }

        json.push_str("    {\n");
        json.push_str(&format!("      \"hash\": \"{}\",\n", card.hash));

        if let Some(ref fh) = card.family_hash {
            json.push_str(&format!("      \"familyHash\": \"{}\",\n", fh));
        } else {
            json.push_str("      \"familyHash\": null,\n");
        }

        json.push_str(&format!("      \"deckName\": \"{}\",\n", escape_json_string(&card.deck_name)));
        json.push_str("      \"location\": {\n");
        json.push_str(&format!("        \"filePath\": \"{}\",\n", escape_json_string(&card.file_path)));
        json.push_str(&format!("        \"lineStart\": {},\n", card.line_start));
        json.push_str(&format!("        \"lineEnd\": {}\n", card.line_end));
        json.push_str("      },\n");

        json.push_str("      \"content\": {\n");
        match &card.content {
            crate::cards::CardContent::Basic { question, answer } => {
                json.push_str("        \"basic\": {\n");
                json.push_str(&format!("          \"question\": \"{}\",\n", escape_json_string(question)));
                json.push_str(&format!("          \"answer\": \"{}\"\n", escape_json_string(answer)));
                json.push_str("        }\n");
            }
            crate::cards::CardContent::Cloze { text, start, end } => {
                json.push_str("        \"cloze\": {\n");
                json.push_str(&format!("          \"text\": \"{}\",\n", escape_json_string(text)));
                json.push_str(&format!("          \"start\": {},\n", start));
                json.push_str(&format!("          \"end\": {}\n", end));
                json.push_str("        }\n");
            }
        }

        json.push_str("      },\n");
        json.push_str("      \"performance\": null\n");
        json.push_str("    }");
    }

    json.push_str("\n  ],\n  \"sessions\": []\n}\n");

    if let Some(output) = output_path {
        fs::write(output, json)?;
    } else {
        print!("{}", json);
    }

    Ok(())
}

fn escape_json_string(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('"', "\\\"")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
        .replace('\t', "\\t")
}
EOF

