use crate::parser::parse_deck;
use std::path::Path;
use std::collections::HashSet;
use std::fs;

pub fn list_orphans(collection_path: &Path) -> std::io::Result<()> {
    let mut _deck_hashes = HashSet::new();

    for entry in fs::read_dir(collection_path)? {
        let entry = entry?;
        let path = entry.path();

        if path.is_file() && path.extension().map_or(false, |ext| ext == "md") {
            let deck_name = path.file_stem().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();

            if let Ok(parsed) = parse_deck(&path, &deck_name) {
                for card in parsed.cards {
                    _deck_hashes.insert(card.hash);
                }
            }
        }
    }

    // Since we don't have a database yet, there are no orphans
    Ok(())
}

pub fn delete_orphans(_collection_path: &Path) -> std::io::Result<()> {
    // Since we don't have a database yet, nothing to delete
    Ok(())
}
