            if let Ok(parsed) = parse_deck(&path, &deck_name) {
                for card in parsed.cards {
                    _deck_hashes.insert(card.hash);
                }
            }
        }
    }

    // Since we don't have a database yet, there are no orphans
    Ok(())
}

pub fn delete_orphans(_collection_path: &Path) -> std::io::Result<()> {
    // Since we don't have a database yet, nothing to delete
    Ok(())
}
