    let tex_macros = extract_tex_macros(&content);

    Ok(ParsedDeck {
        deck_name: deck_name.to_string(),
        cards,
        tex_macros,
    })
}

fn parse_cards(
    content: &str,
    file_path: String,
    deck_name: &str,
) -> std::io::Result<Vec<Card>> {
    let mut cards = Vec::new();
    let lines: Vec<&str> = content.lines().collect();
    let mut i = 0;

    while i < lines.len() {
        let line = lines[i].trim();

        if line.starts_with("Q:") {
            // Parse basic card
            let (card, next_i) = parse_basic_card_from_lines(&lines, i, &file_path, deck_name);
            if let Some(card) = card {
                cards.push(card);
            }
            i = next_i;
        } else if line.starts_with("C:") {
            // Parse cloze card
            let (cloze_cards, next_i) = parse_cloze_card_from_lines(&lines, i, &file_path, deck_name);
            cards.extend(cloze_cards);
            i = next_i;
        } else {
            i += 1;
        }
    }

    Ok(cards)
}

fn parse_basic_card_from_lines(
    lines: &[&str],
    start_line: usize,
    file_path: &str,
    deck_name: &str,
) -> (Option<Card>, usize) {
    let line_start = start_line;
    let mut question_lines = Vec::new();
    let mut answer_lines = Vec::new();
    let mut in_answer = false;
    let mut i = start_line;

    while i < lines.len() {
        let line = lines[i];

        // Check if we've hit another card marker or blank line followed by nothing
        if i > start_line && (line.trim().starts_with("Q:") || line.trim().starts_with("C:")) {
            break;
        }

        if line.trim().starts_with("Q:") && i == start_line {
            let q_content = line[2..].trim();
            if !q_content.is_empty() {
                question_lines.push(q_content.to_string());
            }
        } else if line.trim().starts_with("A:") {
            in_answer = true;
            let a_content = line[2..].trim();
            if !a_content.is_empty() {
                answer_lines.push(a_content.to_string());
            }
        } else if in_answer {
            // Collect answer lines
            if line.is_empty() {
                // Empty line might end the card or be part of it
                // Keep collecting until we see another card marker or real end
                let mut j = i + 1;
                let mut found_marker = false;
                while j < lines.len() {
                    if lines[j].trim().starts_with("Q:") || lines[j].trim().starts_with("C:") {
                        found_marker = true;
                        break;
                    }
                    if !lines[j].trim().is_empty() {
                        break;
                    }
                    j += 1;
                }
                if found_marker {
                    break;
                }
            } else {
                answer_lines.push(line.to_string());
            }
        } else if !in_answer && !line.trim().is_empty() {
            // Still in question
            question_lines.push(line.to_string());
        } else if !in_answer && line.is_empty() && !question_lines.is_empty() {
            // Empty line in question might mean we're looking for answer
            // Keep going for now
        }

        i += 1;

        // Stop if we've gone past reasonable bounds without finding "A:"
        if !in_answer && i - start_line > 100 {
            break;
        }
    }

    if !in_answer || answer_lines.is_empty() {
        return (None, i);
    }

    let question = question_lines.join("\n").trim().to_string();
    let answer = answer_lines.join("\n").trim().to_string();

    let content_str = format!("Q: {}\nA: {}", question, answer);
    let hash = compute_hash(&content_str);

    let card = Card {
        hash,
        family_hash: None,
        deck_name: deck_name.to_string(),
        file_path: file_path.to_string(),
        line_start: line_start,
        line_end: i - 1,
        content: CardContent::Basic { question, answer },
        performance: None,
    };

    (Some(card), i)
}

fn parse_cloze_card_from_lines(
    lines: &[&str],
    start_line: usize,
    file_path: &str,
    deck_name: &str,
) -> (Vec<Card>, usize) {
    let mut cards = Vec::new();
    let line_start = start_line;
    let mut content_lines = Vec::new();
    let mut i = start_line;

    // Collect all lines for this cloze card until we hit another card marker
    while i < lines.len() {
        let line = lines[i];

        if i > start_line && (line.trim().starts_with("Q:") || line.trim().starts_with("C:")) {
            break;
        }

        if i == start_line {
            let c_content = line[2..].trim();
            if !c_content.is_empty() {
                content_lines.push(c_content.to_string());
            }
        } else if !line.trim().is_empty() || !content_lines.is_empty() {
            content_lines.push(line.to_string());
        } else if line.is_empty() && i + 1 < lines.len() {
            // Check if next non-empty line is a card marker
            let mut j = i + 1;
            let mut is_marker = false;
            while j < lines.len() && lines[j].trim().is_empty() {
                j += 1;
            }
            if j < lines.len() && (lines[j].trim().starts_with("Q:") || lines[j].trim().starts_with("C:")) {
                break;
            }
        }

        i += 1;
    }

    let content_str = content_lines.join("\n").trim().to_string();

    // Find all cloze deletions [text]
    let mut cloze_positions = Vec::new();
    let mut in_bracket = false;
    let mut bracket_start = 0;

    for (idx, ch) in content_str.chars().enumerate() {
        if ch == '[' {
            in_bracket = true;
            bracket_start = idx;
        } else if ch == ']' && in_bracket {
            in_bracket = false;
            cloze_positions.push((bracket_start, idx));
        }
    }

    for (cloze_start, cloze_end) in cloze_positions {
        let hash = compute_hash(&format!("{}\x00{}\x00{}", content_str, cloze_start, cloze_end));
        let family_hash = compute_hash(&content_str);

        cards.push(Card {
            hash,
            family_hash: Some(family_hash),
            deck_name: deck_name.to_string(),
            file_path: file_path.to_string(),
            line_start,
            line_end: i - 1,
            content: CardContent::Cloze {
                text: content_str.clone(),
                start: cloze_start,
                end: cloze_end,
            },
            performance: None,
        });
    }

    (cards, i)
}

fn compute_hash(content: &str) -> String {
    let output = std::process::Command::new("sha256sum")
        .arg("-")
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .spawn()
        .and_then(|mut child| {
            use std::io::Write;
            if let Some(mut stdin) = child.stdin.take() {
                stdin.write_all(content.as_bytes())?;
            }
            child.wait_with_output()
        });

    match output {
        Ok(output) => {
            let output_str = String::from_utf8_lossy(&output.stdout);
            output_str.split_whitespace().next().unwrap_or("").to_string()
        }
        Err(_) => "error".to_string(),
    }
}

fn extract_tex_macros(content: &str) -> Vec<String> {
    let mut macros = Vec::new();

    for line in content.lines() {
        if line.contains("\\newcommand") {
            macros.push(line.to_string());
        }
    }

    macros
}
