                    }
                } else {
                    blank_count = 0;
                }
                j += 1;
            }
            if found_marker {
                break;
            }
        }

        answer_lines.push(line.to_string());
        i += 1;
    }

    // Trim trailing blank lines from answer
    while let Some(last) = answer_lines.last() {
        if last.is_empty() {
            answer_lines.pop();
        } else {
